description:
A DLL can catch leaks across its boundary by counting what it hands out. Write a class

```cpp
class OwnershipTracker
{
public:
    int create(const std::string& kind);        // returns a new id: 1, 2, 3...
    bool destroy(int id);                        // false if the id is not live (never made, or destroyed already)
    int live() const;                            // how many objects are live
    std::vector<std::string> leakReport() const; // one line per live object, oldest first
};
```

The leak report lines look like `"leaked xenon #3"`: the kind and the id.

```
OwnershipTracker t;
int a = t.create("xenon");   // 1
int b = t.create("text");    // 2
t.destroy(a);
t.leakReport() == { "leaked text #2" }
```

starter.solution.cpp:
#include <map>
#include <string>
#include <vector>

class OwnershipTracker
{
public:
    int create(const std::string& kind) { return 0; }
    bool destroy(int id) { return false; }
    int live() const { return 0; }
    std::vector<std::string> leakReport() const { return {}; }
};

solution.solution.cpp:
#include <map>
#include <string>
#include <vector>

class OwnershipTracker
{
public:
    int create(const std::string& kind)
    {
        const int id{ ++m_last };
        m_live[id] = kind;
        return id;
    }

    bool destroy(int id) { return m_live.erase(id) > 0; }

    int live() const { return static_cast<int>(m_live.size()); }

    std::vector<std::string> leakReport() const
    {
        std::vector<std::string> lines;
        for (const auto& [id, kind] : m_live) lines.push_back("leaked " + kind + " #" + std::to_string(id));
        return lines;
    }

private:
    std::map<int, std::string> m_live;
    int m_last{ 0 };
};

unitTests:
TEST("the example") { OwnershipTracker t; const int a = t.create("xenon"); const int b = t.create("text"); CHECK_EQ(a, 1); CHECK_EQ(b, 2); CHECK(t.destroy(a)); CHECK_EQ(t.leakReport(), (std::vector<std::string>{ "leaked text #2" })); }
TEST("double destroy") { OwnershipTracker t; const int a = t.create("x"); CHECK(t.destroy(a)); CHECK(!t.destroy(a)); }
TEST("unknown id") { OwnershipTracker t; CHECK(!t.destroy(7)); }
TEST("counts") { OwnershipTracker t; t.create("a"); t.create("b"); t.create("c"); CHECK_EQ(t.live(), 3); t.destroy(2); CHECK_EQ(t.live(), 2); }
TEST("oldest first") { OwnershipTracker t; t.create("a"); t.create("b"); t.create("c"); t.destroy(2); CHECK_EQ(t.leakReport(), (std::vector<std::string>{ "leaked a #1", "leaked c #3" })); }
TEST("clean shutdown") { OwnershipTracker t; t.destroy(t.create("a")); CHECK(t.leakReport().empty()); CHECK_EQ(t.live(), 0); }

